<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\{PeriodGuard,AcademicRules,AcademicDebtService};
class GiaController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$rows=DB::table('gia_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.academic_period_id',$p->id)->select('c.*','g.name as group_name')->orderByDesc('c.id')->get();return view('gia.index',compact('p','groups','rows'));}
 public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','name'=>'required|string|max:255','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on','program_note'=>'nullable|string|max:10000']);$id=DB::table('gia_campaigns')->insertGetId($d+['academic_period_id'=>$p->id,'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->syncStudents($id);return redirect()->route('gia.show',$id);}
 private function syncStudents($id){$c=DB::table('gia_campaigns')->find($id);$ids=DB::table('student_group_memberships')->where(['academic_period_id'=>$c->academic_period_id,'study_group_id'=>$c->study_group_id,'status'=>'active'])->pluck('student_id');if(!$ids->count())$ids=DB::table('students')->where(['current_group_id'=>$c->study_group_id,'status'=>'active'])->pluck('id');foreach($ids as $sid)DB::table('gia_student_results')->updateOrInsert(['gia_campaign_id'=>$id,'student_id'=>$sid],['updated_at'=>now(),'created_at'=>now()]);}
 public function update(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns')->find($id);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['name'=>'required|string|max:255','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on','program_note'=>'nullable|string|max:10000']);DB::table('gia_campaigns')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Кампания ГИА обновлена.');}
 public function status(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns')->find($id);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['status'=>'required|in:draft,active,completed,archived']);if($d['status']==='completed'){abort_if(!DB::table('gia_commission_members')->where('gia_campaign_id',$id)->exists(),422,'Сначала сформируйте комиссию.');abort_if(DB::table('gia_student_results')->where('gia_campaign_id',$id)->whereNull('result')->exists(),422,'Не у всех выпускников внесены результаты.');}DB::table('gia_campaigns')->where('id',$id)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус ГИА изменён.');}
 public function show(Request $r,$id){$this->ok($r);$this->syncStudents($id);$c=DB::table('gia_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.id',$id)->select('c.*','g.name as group_name')->first();abort_if(!$c,404);$events=DB::table('gia_events')->where('gia_campaign_id',$id)->orderBy('starts_at')->get();$members=DB::table('gia_commission_members')->where('gia_campaign_id',$id)->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();$students=DB::table('gia_student_results as gr')->join('students as s','s.id','=','gr.student_id')->where('gr.gia_campaign_id',$id)->select('gr.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->get();return view('gia.show',compact('c','events','members','teachers','students'));}
 public function check(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns')->find($id);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$rows=DB::table('gia_student_results')->where('gia_campaign_id',$id)->get();foreach($rows as $x){$issues=[];$debts=app(AcademicDebtService::class)->count($c->academic_period_id,$x->student_id);if($debts&&AcademicRules::get('gia_require_no_debts',true))$issues[]="Незакрытых задолженностей: $debts";$practice=DB::table('practice_placements')->where(['academic_period_id'=>$c->academic_period_id,'student_id'=>$x->student_id])->where(function($q){$q->whereNull('result')->orWhereNotIn('result',['passed','зачтено','5','4','3']);})->count();if($practice&&AcademicRules::get('gia_require_practice',true))$issues[]="Не закрыта практика: $practice";DB::table('gia_student_results')->where('id',$x->id)->update(['admission_status'=>$issues?'blocked':'ready','admission_issues'=>json_encode($issues,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);}return back()->with('success','Готовность к ГИА пересчитана.');}
 public function event(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns')->find($id);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['type'=>'required|in:demo_exam,defense,exam,consultation,other','name'=>'required|string|max:255','starts_at'=>'nullable|date','place'=>'nullable|string|max:255','note'=>'nullable|string|max:3000']);DB::table('gia_events')->insert($d+['gia_campaign_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function member(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns')->find($id);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['teacher_id'=>'nullable|exists:teachers,id','member_name'=>'nullable|string|max:255','role'=>'required|string|max:100']);abort_if(empty($d['teacher_id'])&&empty($d['member_name']),422);DB::table('gia_commission_members')->insert($d+['gia_campaign_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function result(Request $r,$rid){$this->ok($r);$x=DB::table('gia_student_results as gr')->join('gia_campaigns as c','c.id','=','gr.gia_campaign_id')->where('gr.id',$rid)->select('gr.*','c.academic_period_id')->first();PeriodGuard::writable($x->academic_period_id);abort_unless($x->admission_status==='ready'||$x->admission_status==='admitted',422,'Студент не готов к ГИА.');$d=$r->validate(['result'=>'required|string|max:100','passed'=>'required|boolean','protocol_number'=>'nullable|string|max:100','protocol_date'=>'nullable|date','note'=>'nullable|string|max:3000']);DB::table('gia_student_results')->where('id',$rid)->update($d+['admission_status'=>'admitted','updated_at'=>now()]);return back();}
 public function appeal(Request $r,$rid){$this->ok($r);$x=DB::table('gia_student_results as gr')->join('gia_campaigns as c','c.id','=','gr.gia_campaign_id')->where('gr.id',$rid)->select('gr.*','c.academic_period_id')->first();PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['submitted_on'=>'required|date','reason'=>'required|string|max:5000']);DB::table('gia_appeals')->insert($d+['gia_student_result_id'=>$rid,'status'=>'submitted','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Апелляция зарегистрирована.');}
 public function print(Request $r,$id){$this->ok($r);$c=DB::table('gia_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.id',$id)->select('c.*','g.name as group_name')->first();$students=DB::table('gia_student_results as gr')->join('students as s','s.id','=','gr.student_id')->where('gr.gia_campaign_id',$id)->select('gr.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->get();return view('gia.print',compact('c','students'));}
}